package offline;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Sparse receive-byte ledger. Segments stay disjoint and are never rewritten, so insertions cost
 * only the compared bytes and the newly covered holes; every insertion registers an undo action.
 */
final class ByteStore {

    private static final class Seg {
        final long start;
        final byte[] src;
        final int from;
        final int to;

        Seg(long start, byte[] src, int from, int to) {
            this.start = start;
            this.src = src;
            this.from = from;
            this.to = to;
        }

        long end() {
            return start + (to - from);
        }

        long len() {
            return to - from;
        }
    }

    private final TreeMap<Long, Seg> segs = new TreeMap<>();

    /** Inserts data[offset,offset+length) at absolute position lo, demanding equal overlaps. */
    void insert(long lo, byte[] data, int from, int to, long errOffset, Journal journal) {
        long hi = lo + (to - from);
        if (hi <= lo) {
            return;
        }
        List<Seg> overlap = null;
        Map.Entry<Long, Seg> floor = segs.floorEntry(lo);
        if (floor != null && floor.getValue().end() > lo) {
            overlap = new ArrayList<>();
            overlap.add(floor.getValue());
        }
        for (Seg s : segs.tailMap(lo, false).values()) {
            if (s.start >= hi) {
                break;
            }
            if (overlap == null) {
                overlap = new ArrayList<>();
            }
            overlap.add(s);
        }
        if (overlap == null) {
            overlap = new ArrayList<>(0);
        }
        for (Seg s : overlap) {
            long a = Math.max(s.start, lo);
            long b = Math.min(s.end(), hi);
            for (long p = a; p < b; p++) {
                if (s.src[s.from + (int) (p - s.start)] != data[from + (int) (p - lo)]) {
                    throw new WireException("PROTOCOL_VIOLATION", errOffset);
                }
            }
        }
        List<Seg> added = null;
        long cur = lo;
        for (Seg s : overlap) {
            if (s.start > cur) {
                if (added == null) {
                    added = new ArrayList<>();
                }
                added.add(new Seg(cur, data, from + (int) (cur - lo), from + (int) (s.start - lo)));
            }
            if (s.end() > cur) {
                cur = s.end();
            }
        }
        if (cur < hi) {
            if (added == null) {
                added = new ArrayList<>();
            }
            added.add(new Seg(cur, data, from + (int) (cur - lo), to));
        }
        if (added == null) {
            return;
        }
        for (Seg s : added) {
            segs.put(s.start, s);
        }
        final List<Seg> inserted = added;
        journal.add(new Runnable() {
            @Override
            public void run() {
                for (Seg s : inserted) {
                    segs.remove(s.start);
                }
            }
        });
    }

    /** Sorted, adjacent-merged half-open ranges as interleaved lo/hi pairs. */
    long[] merged() {
        long[] out = new long[segs.size() * 2];
        int k = 0;
        long curStart = -1;
        long curEnd = -1;
        for (Seg s : segs.values()) {
            if (curStart < 0) {
                curStart = s.start;
                curEnd = s.end();
            } else if (s.start <= curEnd) {
                if (s.end() > curEnd) {
                    curEnd = s.end();
                }
            } else {
                out[k++] = curStart;
                out[k++] = curEnd;
                curStart = s.start;
                curEnd = s.end();
            }
        }
        if (curStart >= 0) {
            out[k++] = curStart;
            out[k++] = curEnd;
        }
        return Arrays.copyOf(out, k);
    }

    long unique() {
        long total = 0;
        for (Seg s : segs.values()) {
            total += s.len();
        }
        return total;
    }

    long prefix() {
        if (segs.isEmpty()) {
            return 0;
        }
        Map.Entry<Long, Seg> first = segs.firstEntry();
        if (first.getKey() != 0) {
            return 0;
        }
        long end = 0;
        for (Seg s : segs.values()) {
            if (s.start > end) {
                break;
            }
            if (s.end() > end) {
                end = s.end();
            }
        }
        return end;
    }

    byte[] prefixBytes() {
        long p = prefix();
        if (p <= 0) {
            return new byte[0];
        }
        byte[] out = new byte[(int) p];
        for (Seg s : segs.values()) {
            if (s.start >= p) {
                break;
            }
            System.arraycopy(s.src, s.from, out, (int) s.start, (int) s.len());
        }
        return out;
    }
}
