package offline;

import java.util.Arrays;

/** Append-only log of acknowledged half-open packet-number intervals. */
final class AckLog {
    private long[] lo = new long[32];
    private long[] hi = new long[32];
    private int n = 0;

    void add(long a, long b, Journal journal) {
        if (n == lo.length) {
            int cap = n + (n >> 1) + 8;
            lo = Arrays.copyOf(lo, cap);
            hi = Arrays.copyOf(hi, cap);
        }
        final int old = n;
        lo[n] = a;
        hi[n] = b;
        n++;
        journal.add(new Runnable() {
            @Override
            public void run() {
                n = old;
            }
        });
    }

    int size() {
        return n;
    }

    long lo(int i) {
        return lo[i];
    }

    long hi(int i) {
        return hi[i];
    }

    void sort() {
        ParallelSort.sort(lo, hi, n);
    }
}
